/**
 * @file
 * @brief       Gesture classification with the emlearn random forest of
 *              model.h, generated by tools/train.py
 */

#include "gesture.h"

/* the generated code also defines functions that are not used here */
#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wunused-function"
#pragma GCC diagnostic ignored "-Wunused-parameter"
#include "model.h"
#pragma GCC diagnostic pop

int gesture_classify(const int16_t *features, float *proba)
{
    if (eml_trees_predict_proba(&gesture_model, features, GESTURE_FEATURES,
                                proba, GESTURE_CLASSES) != EmlOk) {
        return -1;
    }
    int best = 0;
    for (int i = 1; i < GESTURE_CLASSES; i++) {
        if (proba[i] > proba[best]) {
            best = i;
        }
    }
    return best;
}
